import{_ as e,o as l,c as a,a3 as s}from"./chunks/framework.bvEHUNtb.js";const x=JSON.parse('{"title":"C-03 三垣体系","description":"梳理紫微、太微、天市三垣的历史沿革、星官结构及其与二十八宿的关系。","frontmatter":{"title":"C-03 三垣体系","description":"梳理紫微、太微、天市三垣的历史沿革、星官结构及其与二十八宿的关系。","category":"guide","outline":"deep","aliases":["三垣体系","三垣二十八宿","紫微垣"]},"headers":[],"relativePath":"topics/traditional-wisdom/common-knowledge/san-yuan-system.md","filePath":"topics/traditional-wisdom/common-knowledge/san-yuan-system.md","lastUpdated":1786982540000}'),n={name:"topics/traditional-wisdom/common-knowledge/san-yuan-system.md"};function d(i,t,r,o,p,g){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="c-03-·-三垣体系-古代星空的中枢坐标" tabindex="-1">C-03 · 三垣体系：古代星空的中枢坐标 <a class="header-anchor" href="#c-03-·-三垣体系-古代星空的中枢坐标" aria-label="Permalink to &quot;C-03 · 三垣体系：古代星空的中枢坐标&quot;">​</a></h1><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 文化通识篇（C系列）· 天文宇宙组<br><strong>版本：</strong> v1.0（2026年8月）<br><strong>前置篇目（必读）：</strong> 09·二十八星宿 / C-02·北斗七星与斗建<br><strong>后续篇目：</strong> C-04·十二建除 / Shu·紫微斗数</p><hr><h2 id="写在前面-为什么要学三垣" tabindex="-1">写在前面：为什么要学三垣？ <a class="header-anchor" href="#写在前面-为什么要学三垣" aria-label="Permalink to &quot;写在前面：为什么要学三垣？&quot;">​</a></h2><p>中国古代的星空，不是一片混沌。</p><p>先人将整个可见天空，划分为一套极其精密的坐标体系：<br><strong>三垣 + 二十八宿</strong>，合称&quot;三垣二十八宿体系&quot;，<br> 是中国古代天文学的核心架构，<br> 也是读懂古籍星象记载、理解术数体系的基础地图。</p><p>不懂三垣：</p><ul><li>读《史记·天官书》《晋书·天文志》，遇到&quot;紫微&quot;&quot;太微&quot;&quot;天市&quot;一头雾水</li><li>学紫微斗数，不知道&quot;紫微&quot;二字从何而来</li><li>读古典小说，&quot;天庭&quot;&quot;帝座&quot;&quot;朝廷星官&quot;等意象无从理解</li></ul><p><strong>本篇目标：</strong><br> 还原三垣体系的完整结构，厘清三垣各自的天文位置、所含星官、文化象征，以及三垣与北斗、二十八宿、术数体系的接口关系。</p><hr><h2 id="一、俯瞰-三垣在整个体系里的位置" tabindex="-1">一、俯瞰：三垣在整个体系里的位置 <a class="header-anchor" href="#一、俯瞰-三垣在整个体系里的位置" aria-label="Permalink to &quot;一、俯瞰：三垣在整个体系里的位置&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>古代天文坐标体系</span></span>
<span class="line"><span>  ├─ 三垣（中央天区）← 本篇核心</span></span>
<span class="line"><span>  │    ├─ 紫微垣（北天极周围·天帝居所）</span></span>
<span class="line"><span>  │    ├─ 太微垣（黄道北·天子朝廷）</span></span>
<span class="line"><span>  │    └─ 天市垣（黄道南·天下市集）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ 二十八宿（黄道带·四象各七宿）← 主干09</span></span>
<span class="line"><span>       ├─ 东方青龙七宿</span></span>
<span class="line"><span>       ├─ 南方朱雀七宿</span></span>
<span class="line"><span>       ├─ 西方白虎七宿</span></span>
<span class="line"><span>       └─ 北方玄武七宿</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三垣 + 二十八宿 = 古代全天星空坐标系</span></span></code></pre></div><p><strong>&quot;垣&quot;字的本义：</strong><br> 垣，城墙也。三垣，即天空中三座&quot;有围墙的城池&quot;——每座垣由两列星官构成&quot;左右垣墙&quot;，围合出一片天区，如同天上的宫城。</p><hr><h2 id="二、三垣体系的历史沿革" tabindex="-1">二、三垣体系的历史沿革 <a class="header-anchor" href="#二、三垣体系的历史沿革" aria-label="Permalink to &quot;二、三垣体系的历史沿革&quot;">​</a></h2><p>【原典】《晋书·天文志》<br> 【原文】&quot;紫宫垣十五星，西藩七，东藩八……太微，天子庭也……天市垣二十二星，东藩十一，西藩十一……&quot;<br> 【版本】唐·房玄龄等撰，二十四史标准本</p><p>三垣体系的<strong>定型</strong>，以《晋书·天文志》为标志。但其思想渊源，可上溯至先秦：</p><table tabindex="0"><thead><tr><th style="text-align:left;">时代</th><th style="text-align:left;">发展阶段</th><th style="text-align:left;">代表文献</th></tr></thead><tbody><tr><td style="text-align:left;">先秦</td><td style="text-align:left;">北极星区&quot;紫宫&quot;概念萌芽</td><td style="text-align:left;">《楚辞》《诗经》零散记载</td></tr><tr><td style="text-align:left;">西汉</td><td style="text-align:left;">五宫体系（中官+四方）初步建立</td><td style="text-align:left;">《史记·天官书》</td></tr><tr><td style="text-align:left;">魏晋</td><td style="text-align:left;">三垣概念基本成型，星官系统化</td><td style="text-align:left;">《晋书·天文志》</td></tr><tr><td style="text-align:left;">隋唐</td><td style="text-align:left;">三垣二十八宿体系完全定型</td><td style="text-align:left;">《步天歌》（丹元子）</td></tr><tr><td style="text-align:left;">宋代</td><td style="text-align:left;">全面整理，星数精确统计</td><td style="text-align:left;">《宋史·天文志》</td></tr></tbody></table><p>【原典】《步天歌》<br> 【原文】紫微垣内细分明，太微垣中帝座清，天市垣里星官聚，三垣分列布天庭。<br> 【版本】唐·丹元子撰（约7世纪），中国古代最重要的认星口诀</p><p>《步天歌》是古代天文学的入门教材，以七言诗的形式，将全天星官逐一记录，三垣二十八宿体系由此得到最广泛的普及与传播。</p><h2 id="三、紫微垣-·-天帝居所" tabindex="-1">三、紫微垣 · 天帝居所 <a class="header-anchor" href="#三、紫微垣-·-天帝居所" aria-label="Permalink to &quot;三、紫微垣 · 天帝居所&quot;">​</a></h2><h3 id="_3-1-天文位置" tabindex="-1">3.1 天文位置 <a class="header-anchor" href="#_3-1-天文位置" aria-label="Permalink to &quot;3.1 天文位置&quot;">​</a></h3><p>紫微垣，位于<strong>北天极周围</strong>，是三垣中最核心、最尊贵的天区。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>位置：北天极（北极星）周围</span></span>
<span class="line"><span>特点：拱极星区，常年可见，永不落于地平线以下</span></span>
<span class="line"><span>范围：大致对应现代星座中的小熊座、大熊座、天龙座、仙王座、仙后座等</span></span></code></pre></div><p>【原典】《史记·天官书》<br> 【原文】&quot;中宫天极星，其一明者，太一常居也；旁三星三公，或曰子属。后句四星，末大星正妃，余三星后宫之属也。环之匡卫十二星，藩臣，皆曰紫宫。&quot;<br> 【版本】西汉·司马迁撰</p><p>司马迁在《天官书》中以&quot;紫宫&quot;描述北极星周围的天区，<br> 这是紫微垣最早的系统性文字记载。<br> &quot;太一常居&quot;——北极星是天帝（太一）的居所，<br> 周围的星官，是天帝的宫廷与臣属。</p><h3 id="_3-2-垣墙结构" tabindex="-1">3.2 垣墙结构 <a class="header-anchor" href="#_3-2-垣墙结构" aria-label="Permalink to &quot;3.2 垣墙结构&quot;">​</a></h3><p>紫微垣由<strong>左垣</strong>（东藩）和<strong>右垣</strong>（西藩）两列星官构成围墙：</p><table tabindex="0"><thead><tr><th style="text-align:left;">垣墙</th><th style="text-align:left;">星数</th><th style="text-align:left;">主要星官</th></tr></thead><tbody><tr><td style="text-align:left;">右垣（西藩）</td><td style="text-align:left;">7星</td><td style="text-align:left;">右枢·上宰·少宰·上弼·少弼·上卫·少卫</td></tr><tr><td style="text-align:left;">左垣（东藩）</td><td style="text-align:left;">8星</td><td style="text-align:left;">左枢·上丞·少丞·上辅·少辅·上卫·少卫·天乙</td></tr></tbody></table><p>垣墙之内，核心星官包括：</p><table tabindex="0"><thead><tr><th style="text-align:left;">星官名</th><th style="text-align:left;">含义</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>北极五星</strong></td><td style="text-align:left;">天帝与皇室</td><td style="text-align:left;">含太子、帝、庶子、后宫、天枢</td></tr><tr><td style="text-align:left;"><strong>勾陈六星</strong></td><td style="text-align:left;">天子护卫</td><td style="text-align:left;">勾陈一即北极星（现代）</td></tr><tr><td style="text-align:left;"><strong>北斗七星</strong></td><td style="text-align:left;">帝车</td><td style="text-align:left;">北斗属紫微垣，是垣内最重要的星官</td></tr><tr><td style="text-align:left;"><strong>天一·太一</strong></td><td style="text-align:left;">天帝本座</td><td style="text-align:left;">最尊贵的星位</td></tr><tr><td style="text-align:left;"><strong>华盖七星</strong></td><td style="text-align:left;">天子仪仗</td><td style="text-align:left;">华盖·杠九星，帝王出行之象</td></tr></tbody></table><blockquote><p>⚠️ <strong>北斗与紫微垣的关系：</strong><br> 北斗七星隶属紫微垣，是垣内地位最高的星官之一。<br> 《史记》称北斗为&quot;帝车&quot;——天帝乘坐北斗巡行天下，北斗居于紫微垣内，正是&quot;帝车停于宫中&quot;的天文象征。</p></blockquote><h3 id="_3-3-文化象征" tabindex="-1">3.3 文化象征 <a class="header-anchor" href="#_3-3-文化象征" aria-label="Permalink to &quot;3.3 文化象征&quot;">​</a></h3><p>紫微垣的核心象征：<strong>天帝的宫城，宇宙的中心</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>紫微垣 → 天帝居所</span></span>
<span class="line"><span>  ↓ 人间对应</span></span>
<span class="line"><span>皇宫（紫禁城）← &quot;紫&quot;字来源于紫微垣</span></span>
<span class="line"><span>             ← &quot;禁&quot;字意为禁地，对应天帝宫城不可侵犯</span></span></code></pre></div><p>北京故宫之所以称&quot;<strong>紫禁城</strong>&quot;，正是取&quot;紫微垣&quot;之&quot;紫&quot;与&quot;禁地&quot;之意——人间皇宫，是天上紫微垣的对应与投影。<br> 这是中国古代&quot;天人合一&quot;宇宙观最直观的建筑体现。</p><h2 id="四、太微垣-·-天子朝廷" tabindex="-1">四、太微垣 · 天子朝廷 <a class="header-anchor" href="#四、太微垣-·-天子朝廷" aria-label="Permalink to &quot;四、太微垣 · 天子朝廷&quot;">​</a></h2><h3 id="_4-1-天文位置" tabindex="-1">4.1 天文位置 <a class="header-anchor" href="#_4-1-天文位置" aria-label="Permalink to &quot;4.1 天文位置&quot;">​</a></h3><p>太微垣，位于<strong>紫微垣之南，黄道以北</strong>，是三垣中象征&quot;朝廷政务&quot;的天区。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>位置：室女座、狮子座、后发座一带</span></span>
<span class="line"><span>特点：黄道北侧，季节性可见</span></span>
<span class="line"><span>范围：大致对应现代星座中的室女座、狮子座、后发座等</span></span></code></pre></div><p>【原典】《晋书·天文志》<br> 【原文】太微，天子庭也，五帝之坐也，十二诸侯府也。其外藩，九卿也。<br> 【版本】唐·房玄龄等撰，二十四史标准本</p><p>这段话极为精炼地道出了太微垣的政治象征：<br> 天子朝廷、五帝之座、诸侯府邸、九卿官署——太微垣，是天上的&quot;中央政府&quot;。</p><h3 id="_4-2-垣墙结构" tabindex="-1">4.2 垣墙结构 <a class="header-anchor" href="#_4-2-垣墙结构" aria-label="Permalink to &quot;4.2 垣墙结构&quot;">​</a></h3><p>太微垣同样由左右垣墙围合：</p><table tabindex="0"><thead><tr><th style="text-align:left;">垣墙</th><th style="text-align:left;">星数</th><th style="text-align:left;">主要星官</th></tr></thead><tbody><tr><td style="text-align:left;">右垣（西藩）</td><td style="text-align:left;">5星</td><td style="text-align:left;">右执法·西上将·西次将·西次相·西上相</td></tr><tr><td style="text-align:left;">左垣（东藩）</td><td style="text-align:left;">5星</td><td style="text-align:left;">左执法·东上将·东次将·东次相·东上相</td></tr></tbody></table><p>垣内核心星官：</p><table tabindex="0"><thead><tr><th style="text-align:left;">星官名</th><th style="text-align:left;">含义</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>五帝座</strong></td><td style="text-align:left;">五方天帝之位</td><td style="text-align:left;">太微垣最核心的星官</td></tr><tr><td style="text-align:left;"><strong>太子·从官</strong></td><td style="text-align:left;">储君与侍从</td><td style="text-align:left;">皇室成员对应</td></tr><tr><td style="text-align:left;"><strong>三公·九卿</strong></td><td style="text-align:left;">朝廷百官</td><td style="text-align:left;">人间官制的天上对应</td></tr><tr><td style="text-align:left;"><strong>郎位·常陈</strong></td><td style="text-align:left;">宫廷侍卫</td><td style="text-align:left;">护卫天子之星</td></tr><tr><td style="text-align:left;"><strong>谒者·三台</strong></td><td style="text-align:left;">礼官·台阁</td><td style="text-align:left;">朝廷礼制星官</td></tr></tbody></table><h3 id="_4-3-文化象征" tabindex="-1">4.3 文化象征 <a class="header-anchor" href="#_4-3-文化象征" aria-label="Permalink to &quot;4.3 文化象征&quot;">​</a></h3><p>太微垣的核心象征：<strong>天子的朝廷，政令的发布中心</strong>。</p><p>古代占星中，太微垣的星象变化，直接对应人间朝廷的政治动向——<br> 某星明亮，对应某官位兴旺；某星暗淡或有异常，则预示对应官位的变动。</p><p>这是古代&quot;星占政治学&quot;的核心运作区域。</p><h2 id="五、天市垣-·-天下市集" tabindex="-1">五、天市垣 · 天下市集 <a class="header-anchor" href="#五、天市垣-·-天下市集" aria-label="Permalink to &quot;五、天市垣 · 天下市集&quot;">​</a></h2><h3 id="_5-1-天文位置" tabindex="-1">5.1 天文位置 <a class="header-anchor" href="#_5-1-天文位置" aria-label="Permalink to &quot;5.1 天文位置&quot;">​</a></h3><p>天市垣，位于<strong>黄道东南方向</strong>，是三垣中象征&quot;民间经济&quot;的天区。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>位置：武仙座、巨蛇座、蛇夫座、天鹰座一带</span></span>
<span class="line"><span>特点：夏秋季节最为显著</span></span>
<span class="line"><span>范围：大致对应现代星座中的武仙座、蛇夫座、巨蛇座等</span></span></code></pre></div><p>【原典】《晋书·天文志》<br> 【原文】天市垣二十二星，东藩十一星，西藩十一星……天市，天子率诸侯幸都市也。<br> 【版本】唐·房玄龄等撰，二十四史标准本</p><p>&quot;天子率诸侯幸都市&quot;——天市垣象征天子巡视市场，是天上的&quot;经济中心&quot;。</p><h3 id="_5-2-垣墙结构" tabindex="-1">5.2 垣墙结构 <a class="header-anchor" href="#_5-2-垣墙结构" aria-label="Permalink to &quot;5.2 垣墙结构&quot;">​</a></h3><p>天市垣的垣墙最为特殊：<br> 左右垣墙各11星，共22星，且<strong>每颗垣星均以诸侯国名命名</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">垣墙</th><th style="text-align:left;">星名（部分）</th></tr></thead><tbody><tr><td style="text-align:left;">东藩（左垣）11星</td><td style="text-align:left;">宋·南海·燕·东海·徐·吴越·齐·中山·九河·赵·魏</td></tr><tr><td style="text-align:left;">西藩（右垣）11星</td><td style="text-align:left;">韩·楚·梁·巴·蜀·秦·周·郑·晋·河间·河中</td></tr></tbody></table><p>这是三垣中最具政治地理意味的设计——<br> 天上的市场，由天下诸侯共同围合而成。</p><p>垣内核心星官：</p><table tabindex="0"><thead><tr><th style="text-align:left;">星官名</th><th style="text-align:left;">含义</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>帝座</strong></td><td style="text-align:left;">天帝临市之座</td><td style="text-align:left;">天市垣中心最亮星</td></tr><tr><td style="text-align:left;"><strong>候·宦者</strong></td><td style="text-align:left;">市场监察官</td><td style="text-align:left;">管理市场秩序</td></tr><tr><td style="text-align:left;"><strong>市楼</strong></td><td style="text-align:left;">市场管理机构</td><td style="text-align:left;">六星，主市场度量</td></tr><tr><td style="text-align:left;"><strong>车肆·列肆</strong></td><td style="text-align:left;">商铺摊位</td><td style="text-align:left;">天上的商业区</td></tr><tr><td style="text-align:left;"><strong>斗·斛</strong></td><td style="text-align:left;">度量衡器具</td><td style="text-align:left;">主公平交易</td></tr></tbody></table><h3 id="_5-3-文化象征" tabindex="-1">5.3 文化象征 <a class="header-anchor" href="#_5-3-文化象征" aria-label="Permalink to &quot;5.3 文化象征&quot;">​</a></h3><p>天市垣的核心象征：<strong>天下的经济命脉，民间的生产与贸易</strong>。</p><p>三垣的政治结构，构成了一个完整的天上社会：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>紫微垣 → 天帝宫城（皇权核心）</span></span>
<span class="line"><span>太微垣 → 天子朝廷（政务中枢）</span></span>
<span class="line"><span>天市垣 → 天下市集（经济民生）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三垣合一 → 完整的天上&quot;国家结构&quot;</span></span></code></pre></div><h2 id="六、三垣与二十八宿的关系" tabindex="-1">六、三垣与二十八宿的关系 <a class="header-anchor" href="#六、三垣与二十八宿的关系" aria-label="Permalink to &quot;六、三垣与二十八宿的关系&quot;">​</a></h2><p>三垣与二十八宿，是古代天文坐标系的<strong>两套互补系统</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">三垣</th><th style="text-align:left;">二十八宿</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>位置</strong></td><td style="text-align:left;">中央天区（以北极为核心）</td><td style="text-align:left;">黄道带（环绕黄道一周）</td></tr><tr><td style="text-align:left;"><strong>功能</strong></td><td style="text-align:left;">定星官等级·政治象征</td><td style="text-align:left;">定日月五星位置·历法基准</td></tr><tr><td style="text-align:left;"><strong>结构</strong></td><td style="text-align:left;">三个有围墙的天区</td><td style="text-align:left;">四象各七宿，共28宿</td></tr><tr><td style="text-align:left;"><strong>核心用途</strong></td><td style="text-align:left;">星占·政治预兆</td><td style="text-align:left;">历法·节气·方位</td></tr><tr><td style="text-align:left;"><strong>与太岁关系</strong></td><td style="text-align:left;">太岁方位参照三垣方位体系</td><td style="text-align:left;">岁星（木星）以二十八宿定位</td></tr></tbody></table><p>【原典】《隋书·天文志》<br> 【原文】垣、宿、星官者，星之集也。为辨诸星，全天分为东南西北中五宫，中宫下分三垣，余者各分七宿，垣、宿又分星官若干。<br> 【版本】唐·魏征等撰，二十四史标准本</p><p>这段话是对三垣二十八宿体系最简洁的官方定义：<br> 全天分五宫，中宫含三垣，四方各含七宿，垣与宿之下，再细分为具体的星官。</p><h2 id="七、三垣在术数体系中的应用" tabindex="-1">七、三垣在术数体系中的应用 <a class="header-anchor" href="#七、三垣在术数体系中的应用" aria-label="Permalink to &quot;七、三垣在术数体系中的应用&quot;">​</a></h2><h3 id="_7-1-紫微斗数" tabindex="-1">7.1 紫微斗数 <a class="header-anchor" href="#_7-1-紫微斗数" aria-label="Permalink to &quot;7.1 紫微斗数&quot;">​</a></h3><p>紫微斗数的命名，直接来源于紫微垣：</p><blockquote><p>&quot;紫微&quot;二字，取自紫微垣——天帝居所，宇宙中心。<br> 紫微斗数以&quot;紫微星&quot;为命盘主星，象征命主在人生格局中的核心地位，如同紫微垣之于整个天空。</p></blockquote><p>紫微斗数中的星曜命名，大量来自三垣星官：</p><ul><li>紫微星（紫微垣·帝座）</li><li>太微星系（太微垣·五帝座）</li><li>天府星（天市垣·帝座）</li></ul><h3 id="_7-2-奇门遁甲" tabindex="-1">7.2 奇门遁甲 <a class="header-anchor" href="#_7-2-奇门遁甲" aria-label="Permalink to &quot;7.2 奇门遁甲&quot;">​</a></h3><p>奇门遁甲的九宫布局，以紫微垣为&quot;中宫&quot;的象征来源：<br> 中宫居中不动（如天禽星），对应紫微垣&quot;居中央，临制四方&quot;的宇宙结构。</p><h3 id="_7-3-风水与方位" tabindex="-1">7.3 风水与方位 <a class="header-anchor" href="#_7-3-风水与方位" aria-label="Permalink to &quot;7.3 风水与方位&quot;">​</a></h3><p>风水中&quot;坐北朝南&quot;的核心原则，<br> 与紫微垣居北天极、面向南方的天文格局直接对应——<br> 天帝居北，朝向南方，<br> 人间皇宫（紫禁城）亦坐北朝南，<br> 是天文格局在地理空间上的投影。</p><h3 id="_7-4-古典文学中的三垣意象" tabindex="-1">7.4 古典文学中的三垣意象 <a class="header-anchor" href="#_7-4-古典文学中的三垣意象" aria-label="Permalink to &quot;7.4 古典文学中的三垣意象&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">意象</th><th style="text-align:left;">来源</th><th style="text-align:left;">常见场景</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;紫微&quot;&quot;紫宫&quot;</td><td style="text-align:left;">紫微垣</td><td style="text-align:left;">指代天帝居所、皇权核心</td></tr><tr><td style="text-align:left;">&quot;太微&quot;&quot;天庭&quot;</td><td style="text-align:left;">太微垣</td><td style="text-align:left;">指代天上朝廷、神仙议政之所</td></tr><tr><td style="text-align:left;">&quot;天市&quot;</td><td style="text-align:left;">天市垣</td><td style="text-align:left;">指代天上的市集、民间繁荣</td></tr><tr><td style="text-align:left;">&quot;紫禁城&quot;</td><td style="text-align:left;">紫微垣</td><td style="text-align:left;">人间皇宫以天上宫城命名</td></tr><tr><td style="text-align:left;">&quot;魁星&quot;</td><td style="text-align:left;">紫微垣·斗魁</td><td style="text-align:left;">科举文化中的文运之星</td></tr></tbody></table><hr><h2 id="八、三垣星数总览" tabindex="-1">八、三垣星数总览 <a class="header-anchor" href="#八、三垣星数总览" aria-label="Permalink to &quot;八、三垣星数总览&quot;">​</a></h2><p>据宋·皇祐年间（1049—1054年）观测记录：</p><table tabindex="0"><thead><tr><th style="text-align:left;">垣名</th><th style="text-align:left;">星座数</th><th style="text-align:left;">正星数</th><th style="text-align:left;">增星数</th><th style="text-align:left;">天区范围（现代星座对应）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>紫微垣</strong></td><td style="text-align:left;">37座（附座2）</td><td style="text-align:left;">163颗</td><td style="text-align:left;">181颗</td><td style="text-align:left;">小熊·大熊·天龙·仙王·仙后等</td></tr><tr><td style="text-align:left;"><strong>太微垣</strong></td><td style="text-align:left;">20座</td><td style="text-align:left;">78颗</td><td style="text-align:left;">100颗</td><td style="text-align:left;">室女·狮子·后发等</td></tr><tr><td style="text-align:left;"><strong>天市垣</strong></td><td style="text-align:left;">19座</td><td style="text-align:left;">87颗</td><td style="text-align:left;">173颗</td><td style="text-align:left;">武仙·蛇夫·巨蛇·天鹰等</td></tr><tr><td style="text-align:left;"><strong>合计</strong></td><td style="text-align:left;">约76座</td><td style="text-align:left;">328颗</td><td style="text-align:left;">454颗</td><td style="text-align:left;">北天极及黄道南北两侧</td></tr></tbody></table><blockquote><p>⚠️ 以上数据以宋代《宋史·天文志》统计为准，<br> 不同历史时期的统计略有出入，以所用文献版本为准。</p></blockquote><h2 id="九、现代视角-三垣是什么" tabindex="-1">九、现代视角：三垣是什么？ <a class="header-anchor" href="#九、现代视角-三垣是什么" aria-label="Permalink to &quot;九、现代视角：三垣是什么？&quot;">​</a></h2><p>用现代天文学语言重新理解三垣：</p><p><strong>三垣，是古人对北天极周围及黄道带两侧天区的系统性划分。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>紫微垣 ≈ 北天极拱极星区（北纬35°以上常年可见）</span></span>
<span class="line"><span>太微垣 ≈ 黄道北侧天区（春夏可见）</span></span>
<span class="line"><span>天市垣 ≈ 黄道东南天区（夏秋可见）</span></span></code></pre></div><p>与西方星座体系的核心区别：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">中国三垣体系</th><th style="text-align:left;">西方星座体系</th></tr></thead><tbody><tr><td style="text-align:left;">划分逻辑</td><td style="text-align:left;">政治社会结构（宫城·朝廷·市集）</td><td style="text-align:left;">神话故事与几何形状</td></tr><tr><td style="text-align:left;">核心功能</td><td style="text-align:left;">星占·政治预兆·历法辅助</td><td style="text-align:left;">航海导航·历法·神话记录</td></tr><tr><td style="text-align:left;">中心参照</td><td style="text-align:left;">北极星（天帝居所）</td><td style="text-align:left;">黄道带（太阳运行轨迹）</td></tr><tr><td style="text-align:left;">文化内涵</td><td style="text-align:left;">天人合一·天上对应人间秩序</td><td style="text-align:left;">神话人格化·英雄叙事</td></tr></tbody></table><p>两套体系，代表了东西方文明对同一片星空的<strong>不同理解方式</strong>：<br> 中国先人看到的是天上的朝廷与秩序，西方先人看到的是神话中的英雄与故事。<br> 这正是文明多样性最美丽的体现。</p><h2 id="十、跨体系接口" tabindex="-1">十、跨体系接口 <a class="header-anchor" href="#十、跨体系接口" aria-label="Permalink to &quot;十、跨体系接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">三垣的作用</th><th style="text-align:left;">具体说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>主干09·二十八星宿</strong></td><td style="text-align:left;">互补关系</td><td style="text-align:left;">三垣定中央，二十八宿定黄道，共同构成全天坐标</td></tr><tr><td style="text-align:left;"><strong>C-02·北斗七星</strong></td><td style="text-align:left;">直接包含</td><td style="text-align:left;">北斗七星隶属紫微垣，是垣内核心星官</td></tr><tr><td style="text-align:left;"><strong>C-01·太岁</strong></td><td style="text-align:left;">方位关联</td><td style="text-align:left;">太岁方位体系以北极为中心，与紫微垣同构</td></tr><tr><td style="text-align:left;"><strong>紫微斗数</strong></td><td style="text-align:left;">命名来源</td><td style="text-align:left;">&quot;紫微&quot;直接取自紫微垣，主星体系源于三垣星官</td></tr><tr><td style="text-align:left;"><strong>奇门遁甲</strong></td><td style="text-align:left;">中宫象征</td><td style="text-align:left;">中宫居中不动，对应紫微垣&quot;居中央临制四方&quot;</td></tr><tr><td style="text-align:left;"><strong>风水</strong></td><td style="text-align:left;">方位原则</td><td style="text-align:left;">坐北朝南原则，源于紫微垣居北天极的天文格局</td></tr><tr><td style="text-align:left;"><strong>古典文学</strong></td><td style="text-align:left;">意象来源</td><td style="text-align:left;">紫禁城·天庭·天市等意象，均源于三垣</td></tr></tbody></table><h2 id="十一、与主干-c系列的连接" tabindex="-1">十一、与主干/C系列的连接 <a class="header-anchor" href="#十一、与主干-c系列的连接" aria-label="Permalink to &quot;十一、与主干/C系列的连接&quot;">​</a></h2><p><strong>接续（前置）：</strong></p><ul><li>← 主干09·二十八星宿（三垣与二十八宿共同构成全天坐标系）</li><li>← C-01·太岁（北极中心的宇宙观，与紫微垣同源）</li><li>← C-02·北斗七星（北斗隶属紫微垣，本篇是C-02的天文背景）</li></ul><p><strong>延伸（后续）：</strong></p><ul><li>→ C-04·十二建除（月建在三垣方位体系中的具体应用）</li><li>→ Shu·紫微斗数（紫微星命名直接来源）</li><li>→ Shu·奇门遁甲（中宫象征结构）</li></ul><h2 id="十二、本章小结" tabindex="-1">十二、本章小结 <a class="header-anchor" href="#十二、本章小结" aria-label="Permalink to &quot;十二、本章小结&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三垣体系 · 四句话总结：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 结构定义：</span></span>
<span class="line"><span>   三垣 = 紫微垣（北天极）+ 太微垣（黄道北）+ 天市垣（黄道东南）</span></span>
<span class="line"><span>   每垣由左右垣墙围合，内含若干星官</span></span>
<span class="line"><span>   与二十八宿合称&quot;三垣二十八宿&quot;，是古代全天坐标系</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 象征体系：</span></span>
<span class="line"><span>   紫微垣 = 天帝宫城（宇宙中心·皇权象征）</span></span>
<span class="line"><span>   太微垣 = 天子朝廷（政务中枢·百官之位）</span></span>
<span class="line"><span>   天市垣 = 天下市集（经济民生·诸侯围合）</span></span>
<span class="line"><span>   三垣合一，构成完整的天上&quot;国家结构&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 定型历史：</span></span>
<span class="line"><span>   思想渊源先秦，《史记·天官书》初步建立</span></span>
<span class="line"><span>   《晋书·天文志》定型，《步天歌》普及</span></span>
<span class="line"><span>   宋代完成精确星数统计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 术数接口：</span></span>
<span class="line"><span>   紫微斗数命名直接来源于紫微垣</span></span>
<span class="line"><span>   奇门中宫象征源于紫微垣居中临制的结构</span></span>
<span class="line"><span>   风水坐北朝南原则，与紫微垣天文格局同构</span></span></code></pre></div><hr><h2 id="引用来源" tabindex="-1">引用来源 <a class="header-anchor" href="#引用来源" aria-label="Permalink to &quot;引用来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">来源</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">《史记·天官书》，西汉·司马迁撰</td><td style="text-align:left;">&quot;中宫天极星……环之匡卫十二星，藩臣，皆曰紫宫&quot;——紫微垣最早系统记载</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">《晋书·天文志》，唐·房玄龄等撰（二十四史标准本）</td><td style="text-align:left;">三垣定义·垣墙星数·&quot;太微，天子庭也&quot;·&quot;天市，天子率诸侯幸都市也&quot;</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">《隋书·天文志》，唐·魏征等撰（二十四史标准本）</td><td style="text-align:left;">&quot;全天分为东南西北中五宫，中宫下分三垣&quot;——三垣二十八宿体系官方定义</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">《步天歌》，唐·丹元子撰（约7世纪）</td><td style="text-align:left;">三垣二十八宿全天星官认星口诀，三垣体系最广泛的普及文本</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">《宋史·天文志》，元·脱脱等撰（二十四史标准本）</td><td style="text-align:left;">宋皇祐年间三垣星数精确统计（紫微垣37座163正星，太微垣·天市垣详细数据）</td></tr></tbody></table><hr><p><strong>前置篇：</strong> C-02·北斗七星与斗建<br><strong>后续篇：</strong> C-04·十二建除</p>`,110)])])}const y=e(n,[["render",d]]);export{x as __pageData,y as default};
